/**
 * 符号表
 */

cc.Class({
    extends: require("LMSlots_Symbol_Base"),

    properties: {
        _type:"normal",

    },

    Init:function(idx,node){
        this._super(idx,node);

        this.setMaskVisible(false);
    },

    setSymType(type){
        this._type = type;
    },

    ShowRandomSymbol(){
        this._super();

        if(this._id === 5){
            let num = Global.random(1,5) * cc.vv.gameData.GetTotalBet();
            this.setNum(num);
        }

        if( cc.vv.gameData.isFreeGame() || cc.vv.gameData.IsBonusGame() ){
        } else {
            this.setMaskVisible(true)
        }
    },

    ShowById(id,data){

        if(this._type === "bonus"){
            this._id = id
            this._data = data
            this._state = "normal";

            if(this._showNode){
                this._showNode.active = false
            }
            let cfg = cc.vv.gameData.getGameCfg()
            if(cfg.symbol[id] && cfg.symbol[id].bonus_node){
                this._showNode = cc.find(cfg.symbol[id].bonus_node,this.node)
                this._showNode.active = true
            }
        } else {
            this._super(id,data);
        }

        this.setNum();
        this.setPool();
        this.setNumAndJpPosition();
        if(data){
            if(data.pool > 0){
                this.setPool(data.pool);
            }

            if(data.coin > 0){
                this.setNum(data.coin);
            }

            if(data.type === 3){
                this.setNumAndJpPosition();
            }
        }

        this.setMaskVisible(false);
    },

    setMaskVisible(isMask) {
        let cfg = cc.vv.gameData.getGameCfg()
        if(cfg.symbol[this._id] && cfg.symbol[this._id].node && cfg.symbol[this._id].isMask){
            let showNode = cc.find(cfg.symbol[this._id].node,this.node)
            if (isMask) {
                if(cc.vv.gameData.getSymbolDark()){
                    showNode.color = new cc.Color(80, 80, 80);
                }else {
                    showNode.color = new cc.Color(200, 200, 200);
                }
            }
            else {
                showNode.color = cc.Color.WHITE;
            }
        }
    },

    getSymbolIdx(){
        if(this._type === "bonus"){
            return this._bonusIndex;
        } else {
            return this._symbolIdx;
        }
    },

    getReelIdx(){
        return this._reelIdx;
    },

    setNum(num){
        let lbl = cc.find("lbl",this.node);
        if (num){
            let font = null;
            if(this._id === 5){
                font = cc.vv.gameData.GetFontByName("theme197_baoshizi1_0")
            } else {
                font = cc.vv.gameData.GetFontByName("theme197_baoshizi2_0")
            }

            lbl.active = true;
            lbl.getComponent(cc.Label).font = font;
            lbl.getComponent(cc.Label).string = Global.formatNumShort(num,0);
        }else {
            lbl.active = false;
            lbl.getComponent(cc.Label).string = "";
        }
        lbl.y = 5.5;
    },

    setPool(jp){
        let spr_jp = cc.find("spr_jp",this.node);

        if(jp){
            spr_jp.active = true;
            let pic = cc.js.formatStr("theme197_s_jp%s",5-jp);
            let atlas = cc.vv.gameData.GetAtlasByName("symbols")
            spr_jp.getComponent(cc.Sprite).spriteFrame = cc.vv.gameData.GetAtlasByName("symbols").getSpriteFrame(pic);
        } else {
            spr_jp.active = false;
        }
        spr_jp.position = cc.v2(0, 0);
    },

    setNumAndJpPosition(){
        let lbl = cc.find("lbl",this.node);
        let spr_jp = cc.find("spr_jp",this.node);
        if(lbl.active && spr_jp.active){
            cc.find("spr_add",this.node).active = true;
            lbl.y = -24;
            spr_jp.position = cc.v2(0, 28);
        } else {
            cc.find("spr_add",this.node).active = false;
        }
    },

    setBonusIndex(index){
        this._bonusIndex = index
    },

    // 紫色宝石停止时动画
    playPurpleGemStopAnim(){
        let id = this._id;
        let cfg = cc.vv.gameData.getGameCfg();
        if(cfg.symbol[id] && cfg.symbol[id].win_node && cfg.symbol[id].stop_ani){
            if(this._showNode){
                this._showNode.active = false
            }
            this._showNode = cc.find(cfg.symbol[id].win_node,this.node)
            this._showNode.active = true

            if(cfg.symbol[id].stop_ani.name != ""){
                let nodeSp = this._showNode.getComponent(sp.Skeleton)
                if(nodeSp){
                    nodeSp.setAnimation(0,cfg.symbol[id].stop_ani.name,false);
                    if(cfg.symbol[id].await_ani.name != ""){
                        nodeSp.addAnimation(0,cfg.symbol[id].await_ani.name,true);
                    }
                }
            }
        }
    },

    // 紫色宝石图标播放粒子特效后动画
    playPurpleGemIdleAnim(){
        let id = this._id;
        let cfg = cc.vv.gameData.getGameCfg();
        if(cfg.symbol[id] && cfg.symbol[id].win_node && cfg.symbol[id].idle_ani){
            if(this._showNode){
                this._showNode.active = false
            }
            this._showNode = cc.find(cfg.symbol[id].win_node,this.node)
            this._showNode.active = true

            if(cfg.symbol[id].idle_ani.name != ""){
                let nodeSp = this._showNode.getComponent(sp.Skeleton)
                if(nodeSp){
                    nodeSp.setAnimation(0,cfg.symbol[id].idle_ani.name,true);
                }
            }
        }
    },

    // bonus游戏图标停止动画
    playBonusStopAnim(){
        let id = this._id;
        let cfg = cc.vv.gameData.getGameCfg();
        if(cfg.symbol[id] && cfg.symbol[id].win_node && cfg.symbol[id].stop_ani){
            if(this._showNode){
                this._showNode.active = false
            }
            this._showNode = cc.find(cfg.symbol[id].win_node,this.node)
            this._showNode.active = true

            if(cfg.symbol[id].stop_ani.name != ""){
                let nodeSp = this._showNode.getComponent(sp.Skeleton)
                if(nodeSp){
                    nodeSp.setAnimation(0,cfg.symbol[id].stop_ani.name,false);
                    if(cfg.symbol[id].idle_ani.name != ""){
                        nodeSp.addAnimation(0,cfg.symbol[id].idle_ani.name,true);
                    }
                }
            }
        }
    },

    // bonus图标待机
    playBonusIdleAnim(){
        let id = this._id;
        let cfg = cc.vv.gameData.getGameCfg();
        if(cfg.symbol[id] && cfg.symbol[id].win_node && cfg.symbol[id].idle_ani){
            if(this._showNode){
                this._showNode.active = false
            }
            this._showNode = cc.find(cfg.symbol[id].win_node,this.node)
            this._showNode.active = true
            if(cfg.symbol[id].idle_ani.name != ""){
                let nodeSp = this._showNode.getComponent(sp.Skeleton)
                if(nodeSp) {
                    nodeSp.setAnimation(0, cfg.symbol[id].idle_ani.name, true);
                }
            }
        }
    },

    // bonus图标结算时动画
    playBonusEndAnim(){
        let id = this._id;
        let cfg = cc.vv.gameData.getGameCfg();
        if(cfg.symbol[id] && cfg.symbol[id].win_node && cfg.symbol[id].end_ani){
            if(this._showNode){
                this._showNode.active = false
            }
            this._showNode = cc.find(cfg.symbol[id].win_node,this.node)
            this._showNode.active = true
            if(cfg.symbol[id].end_ani.name != ""){
                let nodeSp = this._showNode.getComponent(sp.Skeleton)
                if(nodeSp) {
                    nodeSp.setAnimation(0, cfg.symbol[id].end_ani.name, true);
                }
            }
        }
    },

    // bonus结算时图标爆炸动画
    playBonusBombAnim(bPlay){
        let node = cc.find("bouns_bomb", this.node);

        if(bPlay){
            node.active = true;
            node.getComponent(sp.Skeleton).setAnimation(0,"animation", false);
        } else {
            node.active = false;
        }
    },

    // bonus结算时收集动画
    playBonusShoujiAnim(bPlay){
        let node = cc.find("bouns_shouji", this.node);

        if(bPlay){
            node.active = true;
            node.getComponent(sp.Skeleton).setAnimation(0,"animation", true);
        } else {
            node.active = false;
        }
    },

    //触发动画
    //触发了才播放的。比如已经3个scatter已经触发了免费。这个和中奖的还不一样
    playTriggerAnimation(bLoop){
        let isPlay = false
        let id = this._id
        let cfg = cc.vv.gameData.getGameCfg()
        if(cfg.symbol[id] && cfg.symbol[id].win_node && cfg.symbol[id].trigger_ani){
            this._state = "trigger";
            if(this._showNode){
                this._showNode.active = false
            }
            let aniNode = this.setAnimationToTop(true)
            aniNode.active = true
            let topShowNode = cc.find(cfg.symbol[id].win_node,aniNode)
            topShowNode.active = true
            if(cfg.symbol[id].trigger_ani.name != ""){
                aniNode.zIndex = cfg.symbol[id].trigger_ani.zIndex - this._symbolIdx + this._reelIdx*10 + 100;
                isPlay = true
                let nodeSp = topShowNode.getComponent(sp.Skeleton)
                if(nodeSp){
                    bLoop = bLoop === false ? bLoop : true;
                    nodeSp.setAnimation(0,cfg.symbol[id].trigger_ani.name,bLoop)
                }
            }
        }
        return isPlay
    },
})
