
cc.Class({
    extends: require("LMSlots_Logic_Base"),

    properties: {

    },

    //初始化公共组件
    InitCommComponent:function() {
        this._super();

        let script_collect = this.node.addComponent("GodnessOfLove_Collect")
        script_collect.Init()
        cc.vv.gameData.SetCollectScript(script_collect);

        let script_popup = this.node.addComponent("GodnessOfLove_Popup")
        script_popup.Init()
        cc.vv.gameData.SetPopupScript(script_popup);

        let script_bonus = this.node.addComponent("GodnessOfLove_BonusGame")
        script_bonus.Init()
        cc.vv.gameData.SetBonusScript(script_bonus);

        let script_pool = cc.find("safe_node/bonus_slots/LMSlots_PrizePool_1", this.node).getComponent("GodnessOfLove_PrizePool");
        cc.vv.gameData.SetPoolScript(script_pool);
    }

});