let jackpotNames = ['MINI','MINOR','MAJOR','GRAND']  //节点名称
cc.Class({
    extends: require("LMSlots_PrizePool_Base"),

    properties: {

    },

    // LIFE-CYCLE CALLBACKS:

    // onLoad () {},

    // start () {
    //
    // },

    //各个节点上的解锁/锁定表现
    ShowNodeLockByNode:function(node,bLock,unLockBet,poolType,bInit){
        // this.updataJackPoolLock(poolType,bLock);

        let targetJpNode = node
        let spine_lock = cc.find("jpshangsuo",targetJpNode)
        if(targetJpNode){
            this.showTipNode(bLock,poolType,bInit);

            let aniType = [4,3,2,1] //对应奖池的动画前缀类型
            if(bLock){
                spine_lock.active = true;
                if(bInit){
                    spine_lock.getComponent(sp.Skeleton).setAnimation(0,cc.js.formatStr("animation%s_%s",aniType[poolType],2),true)
                } else {
                    Global.SlotsSoundMgr.playEffect("jp_lock");
                    spine_lock.getComponent(sp.Skeleton).setAnimation(0,cc.js.formatStr("animation%s",aniType[poolType]),false)
                    spine_lock.getComponent(sp.Skeleton).addAnimation(0,cc.js.formatStr("animation%s_%s",aniType[poolType],2),true)
                }
            }
            else{
                if(bInit){
                    spine_lock.getComponent(sp.Skeleton).setAnimation(0,cc.js.formatStr("animation%s_%s",aniType[poolType],1),false)
                } else {
                    Global.SlotsSoundMgr.playEffect("jp_unlock");
                    spine_lock.getComponent(sp.Skeleton).setAnimation(0,cc.js.formatStr("animation%s_%s",aniType[poolType],1),false)
                    //spine_lock.getComponent(sp.Skeleton).addAnimation(0,"animation4",true)
                }
            }
        }
    },

    showTipNode(bLock,poolType,bInit){

        for (let i = 0; i < jackpotNames.length; i++){
            let tips = cc.find( cc.js.formatStr("prizePool_%s/tip",jackpotNames[i]), this.node);

            if(!bInit && poolType === i) {
                if (bLock) {
                    cc.find("spr_lock", tips).active = true
                    cc.find("spr_unlock", tips).active = false
                    tips.scale = 0
                    cc.tween(tips)
                        .to(0.5, {scale: 1}, {easing: "backOut"})
                        .delay(0.5)
                        .to(0.5, {scale: 0}, {easing: "backIn"}).start()
                } else {
                    cc.find("spr_lock", tips).active = false
                    cc.find("spr_unlock", tips).active = true
                    tips.scale = 0
                    cc.tween(tips)
                        .to(0.5, {scale: 1}, {easing: "backOut"})
                        .delay(0.5)
                        .to(0.5, {scale: 0}, {easing: "backIn"}).start()
                }
            }
            else {
                cc.find("spr_lock",tips).active = false;
                cc.find("spr_unlock",tips).active = false;
                tips.stopAllActions();
                tips.scale = 0
            }
        }
    },

    //  bonus游戏赢得奖池动画
    showWinJp(idx, bShow){

        let spNode = cc.find(cc.js.formatStr("prizePool_%s/spine_win",jackpotNames[idx-1]),this.node);
        spNode.active = bShow;
    },

    poolIsLock(idx){
        let poolNode = cc.find(cc.js.formatStr("prizePool_%s",jackpotNames[idx-1]),this.node);
        let isLock = poolNode.getComponent("LMSlotMachine_PrizePool").isLocked();
        return isLock;
    },


    // update (dt) {},
});
