// Learn Attribute:
//  - https://docs.cocos.com/creator/manual/en/scripting/reference/attributes.html
// Learn life-cycle callbacks:
//  - https://docs.cocos.com/creator/manual/en/scripting/life-cycle-callbacks.html

cc.Class({
    extends: cc.Component,

    properties: {
        _maskList:[],
        _holderData:[],
    },

    // LIFE-CYCLE CALLBACKS:

    // onLoad () {},

    start () {

    },

    Init:function(idx,nCount,holdCount, aniNode){
        this._reelIdx = idx
        this._holderCount = holdCount
        this._nCount = nCount
        this._symbols = []
        this._topAniNode = aniNode

        for (let index = 0; index < this._holderCount; index++) {
            let holdInfo = {}
            let mask = cc.find("mask_" + (index+1),this.node)
            holdInfo.node = cc.find("holder",mask)
            holdInfo.OrigPosY = holdInfo.node.position.y
            holdInfo.symbols = []
            holdInfo.isPlay = true;
            this._maskList.push(mask);
            this._holderData.push(holdInfo)
        }


        this.LoadSymbols()
    },

    setHolderPlay(row,bPlay){
        this._holderData[row].isPlay = bPlay;
    },

    getHolderPlay(row){
        return this._holderData[row].isPlay
    },

    //获取当前的reelIdx
    GetReelIdx:function(){
        return this._reelIdx
    },

    //创建整列的symbols
    LoadSymbols:function(){
        let cfg = cc.vv.gameData.getGameCfg()
        let url = cfg.symbolPrefab
        if(!this._symbolTemplete){
            this._symbolTemplete = cc.vv.gameData.GetPrefabByName(url)
        }

        for (let index = 0; index < this._holderData.length; index++) {
            let info = this._holderData[index]
            for(let i = 0; i < 2; i++){
                let cfg = cc.vv.gameData.getGameCfg()
                let node = cc.instantiate(this._symbolTemplete)
                node.parent = info.node
                let scp = node.addComponent(cfg.scripts.Symbols)
                let idx = i+1; //行号
                scp.Init(idx,this._topAniNode)
                scp.SetSymbolReelIdx(this._reelIdx)
                scp.setBonusIndex(index)
                // scp.ShowById(cfg.emptyId[0])

                scp.setSymType("bonus");

                info.symbols.push(scp)
            }
            this.ReLayOut(info.symbols)
        }
    },

    //符号重排设置位置
    ReLayOut:function(symbols){
        for (let i = 0; i < symbols.length; i++) {
            let element = symbols[i];
            element.node.position = this.GetSymbolPosByRow(i)
            element.SetSymbolIdx(i);
        }
    },

    //按行获取symbol
    //row 0开始
    GetSymbolByRow:function(row){
        return this._holderData[row].symbols[0]
    },

    //获取symbol的位置
    GetSymbolPosByRow:function(row){
        let cfg = cc.vv.gameData.getGameCfg()
        return cc.v2(0,(row+0.5)*cfg.symbolSize.height)
    },


    //旋转
    StartMove:function(){
        this._result = null
        let cfg = cc.vv.gameData.getGameCfg()
        this._curY = 0
        this._bMoving = true
        this._bStoping = false
        this._fillCount = 0

        for (let info of this._holderData) {
            if(info.isPlay){
                for (let symbol of info.symbols) {
                    symbol.node.active = true
                    symbol.StartMove()
                }
            }

        }

        this._speed = cfg.speed
        this._offset = cfg.symbolSize.height

    },


    //停止
    StopMove:function(delayTime){
        if(!this._bMoving) return   //不在转动了也不停止

        this._bStoping = true
        this._stopTime = delayTime
    },

    //立即停止
    StopMoveRightNow:function(){
        this._stopRightNow = true
    },


    //列停止
    OnReelSpinEnd:function(){
        let slots = cc.vv.gameData.GetBonusScript()
        let lastReelStopIdx = slots.GetLastStopReelIdx()
        if(this._reelIdx == lastReelStopIdx){
            //所有列都停止了
            slots.OnSpinEnd()
        }
    },

    //设置结果
    //[{sid:*,data:*}...]
    SetResult:function(val){
        this._result = val
        // this._cloneResult = Global.copy(this._result);
        // cc.log("this._result:",this._cloneResult)
    },


    //更新位置
    UpdatePosition:function(dt){
        this._stopTime = this._stopTime - dt
        if(this._stopTime <= 0 && this._bStoping && this._result && this._stopRightNow){
            //立即停止：
            let cfg = cc.vv.gameData.getGameCfg()
            this._speed = Math.max(cfg.speed/2,this._speed - cfg.speed*dt)
        }

        this._curY += dt*this._speed
        if(this._curY > this._offset){
            //移动了一个symbol的距离，holder归位
            this._curY = 0
            for (let info of this._holderData) {
                if(!info.isPlay){
                    if(this._stopTime <= 0 && this._bStoping && this._result) {
                        if (this._fillCount < this._holderCount) {
                            this._result.shift()
                            this._fillCount++;
                        }
                        else{
                            this._bMoving = false
                        }
                    }
                }else {
                    info.node.y = info.OrigPosY

                    let sid = 0
                    let data = null
                    if(this._stopTime <= 0 && this._bStoping && this._result) {
                        if(this._fillCount < this._holderCount){
                            //设置一个格子的symbol
                            let item = this._result.shift()
                            sid = item.sid
                            data = item.data
                            this._fillCount++
                        }
                        else{
                            this._bMoving = false
                        }
                    }

                    let symbol = info.symbols.shift()
                    if(sid > 0){
                        symbol.ShowById(sid,data)
                    }
                    else{
                        symbol.ShowRandomSymbol()
                    }
                    info.symbols.push(symbol)
                    this.ReLayOut(info.symbols)
                }


            }
        }else{
            for (let info of this._holderData) {
                if(info.isPlay){
                    info.node.y = info.OrigPosY - this._curY
                }

            }
        }

        if(!this._bMoving){
            this.OnReelBounsAction()
        }
    },

    //回弹动作最低点
    OnReelBounsActionDeep:function(){
        // let cfg = cc.vv.gameData.getGameCfg()
        // for (let index = 0; index < this._holderData.length; index++) {
        //     let info = this._holderData[index];
        // info.symbols[0].BonusStopMove()
        // }
        let slots = cc.vv.gameData.GetBonusScript()
        slots.OnReelBounsActionDeep(this._reelIdx)
    },

    //列回弹动作完成之后
    OnReelBounsActionEnd:function(){
        let slots = cc.vv.gameData.GetBonusScript()
        slots.OnReelBounsActionEnd(this._reelIdx)
        this.OnReelSpinEnd()
    },

    //列回弹动作
    OnReelBounsAction:function() {
        let cfg = cc.vv.gameData.getGameCfg()
        let distance = cfg.bounceInfo ? cfg.bounceInfo.distance : 30
        let time = cfg.bounceInfo ? cfg.bounceInfo.time : 0.3
        for (let info of this._holderData) {
            if(info.isPlay){
                cc.tween(info.node)
                    .to(distance / this._speed, {position: cc.v2(info.node.x, info.OrigPosY - distance)})
                    .to(time, {position: cc.v2(info.node.x, info.OrigPosY)})
                    .start()
            }
        }
        cc.tween(this.node)
            .delay(distance / this._speed)
            .call(this.OnReelBounsActionDeep.bind(this))
            .delay(time)
            .call(this.OnReelBounsActionEnd.bind(this))
            .start()
    },

    update (dt) {
        if(this._bMoving){
            this.UpdatePosition(dt)
        }
    },

    // update (dt) {},
});
