cc.Class({
    extends: require("LMSlots_Slots_Base"),

    properties: {
        // _isFiveGem:false,   // 当前为5个宝石触发bonus

    },

    start () {

    },

    Init(top,bottom){
        this._node_banner = cc.find("node_banner", this.node);
        this._spine_free_shouji = cc.find("spine_free_shouji", this.node.parent);
        this._spine_js = cc.find("spine_bonus_js", this.node.parent);
        this._spine_free_shouji.active = false;
        this._spine_js.active = false;

        this._super(top,bottom);
    },

    // 断线重连
    async ReconnectShow(){
        // this._super();
        this._bottomScript.ShowBtnsByState("moveing_1");

        if(cc.vv.gameData.GetBonusState()){

            await new Promise(async (sucess, failed)=> {
                cc.vv.gameData.GetBonusScript().enterBonusGame(sucess);
            })
        }

        if (cc.vv.gameData.GetTotalFree() > 0){
            this.ShowGameview(true);
            if(cc.vv.gameData.GetTotalFree() > 0 && cc.vv.gameData.GetFreeTime() == 0){
                await this.CheckExitFreeGame();
            }
        } else {
            this.ShowGameview(false);
        }

        this._topScript.StopMove()
        this._bottomScript.CanDoNextRound();
    },

    onMsgSpine(msg){
        if(cc.vv.gameData.IsBonusGame()){
            cc.vv.gameData.GetBonusScript().onMsgSpine(msg)
        } else {
            this._super(msg);
        }
    },

    SetSlotsResult:function(cards){
        //把结果按卷轴结果整理
        let acRow = cards.length / this._col;
        let reelResults = [];
        for(let i = 0;i < cards.length; i++){
            let row = Math.floor(i / acRow);
            let col = i % this._col;
            //配置中有没有这个元素
            if(this._cfg.symbol[cards[i]]){
                let res = {};
                res.sid = cards[i]; //符号id

                // bonus宝石
                let infoData = cc.vv.gameData.GetBonusInfo();
                for (let key in infoData){
                    let idx = Number(key.substring("idx_".length));
                    if(idx === i+1){
                        res.data = infoData[key];
                    }
                }

                // free紫色宝石
                if(this._gameInfo.freeBonusInfo && this._gameInfo.freeBonusInfo.info){
                    let info = this._gameInfo.freeBonusInfo.info
                    for(let m = 0; m < info.length; m++){
                        if(info[m].idx === i+1){
                            let data = {};
                            data.coin = info[m].num;

                            res.data = data;
                            break;
                        }
                    }
                }

                if(!reelResults[col]) reelResults[col] = [];
                reelResults[col].unshift(res);
            }
        }

        for(let i = 0; i < this._reels.length; i++){
            let item = this._reels[i]
            let reelRes = reelResults[i]
            item.SetResult(reelRes)
        }
    },

    StartMove(){
        if(cc.vv.gameData.IsBonusGame()){
            cc.vv.gameData.GetBonusScript().StartMove()
        } else {
            this._super();
            Global.SlotsSoundMgr.playNormalBgm();

            if( cc.vv.gameData.isFreeGame() || cc.vv.gameData.IsBonusGame() ) {
            }else {
                cc.vv.gameData.setSymbolDark(true);
            }
        }
    },

    StopMove(){
        if(cc.vv.gameData.IsBonusGame()){
            cc.vv.gameData.GetBonusScript().StopMove()
        } else {
            this._super();
        }
    },

    //回弹动作之前
    OnReelBounsActionBefore(colIdx){
        this._super(colIdx);

        cc.vv.gameData.setSymbolDark(false);
    },

    OnReelBounsActionDeep(colIdx){
        this._super(colIdx);
        for(let row = 0; row < this._row; row++){
            let syc = this._reels[colIdx].GetSymbolByRow(row)
            let id = syc.GetShowId();

            if(id === 3){   //+1树墩
                Global.SlotsSoundMgr.playEffect("spin_add");
                syc.playStopAnimation();
            }

            if(id === 4){   // 紫色宝石
                Global.SlotsSoundMgr.playEffect("bonus_land");
                syc.playPurpleGemStopAnim();
            }


        }
    },

    DoCheckReelAnti:function(colIdx){
        if(cc.vv.gameData.IsBonusGame()){
            return;
        }
        this._super(colIdx);
    },

    OnSpinEnd(){
        this.onSpinEndAction();

    },

    async onSpinEndAction(){

        // 显示中奖路线
        this.ShowWinTrace()

        // 紫色宝石总赢分，会加在返回的wincoin中，动画过程须客户端自行减去
        let subCoin = 0;
        let freeBonusInfo = this._gameInfo.freeBonusInfo;
        if(freeBonusInfo && freeBonusInfo.winCoin > 0){
            subCoin = freeBonusInfo.winCoin;
        }

        // 显示底部赢钱
        let nWin = cc.vv.gameData.GetGameWin() - subCoin
        let nTotal = nWin
        if(cc.vv.gameData.GetTotalFree() > 0 && cc.vv.gameData.GetTotalFree() != cc.vv.gameData.GetFreeTime()){
            nTotal = cc.vv.gameData.GetGameTotalFreeWin() - subCoin
        }
        await new Promise((sucess, failed)=>{
            this.ShowBottomWin(nWin,nTotal,true,sucess)
        });

        // 免费游戏中有紫色宝石
        if(freeBonusInfo && freeBonusInfo.winCoin > 0){
            await this.playPurpleWinCoin()
        }

        // 触发小游戏
        if(this._gameInfo.bonusGame && this._gameInfo.bonusGame.start){

            cc.vv.gameData.GetCollectScript().addOneItem();

            await this.CheckTriggerBonusGame();
        }

        // 触发免费
        let freeInfo = this._gameInfo.freeResult.freeInfo;
        if (freeInfo && freeInfo.freeCnt > 0){

            await this.CheckEnterFreeGame();
        }

        // 免费结束
        if(this._gameInfo.allFreeCnt > 0 && this._gameInfo.freeCnt == 0){
            await this.CheckExitFreeGame();
        }

        this.CanDoNextRound();
    },

    // 免费游戏中紫色图标赢钱动画
    async playPurpleWinCoin(){
        return new Promise(async (sucess, failed)=> {
            let info = this._gameInfo.freeBonusInfo.info;
            let restInfo = Global.copy(info);

            for (let col = 0; col < this._col; col++) {
                for (let row = this._row - 1; row >= 0; row--) {    // 从上往下
                    let syc = this._reels[col].GetSymbolByRow(row)

                    let idx = this.getIdxByRowCol(row, col);
                    let winCoin = 0;
                    for(let i = 0; i < restInfo.length; i++){
                        if(idx === restInfo[i].idx){
                            Global.SlotsSoundMgr.playEffect("win_fly");
                            winCoin = restInfo[i].num;
                            syc.playPurpleGemIdleAnim();
                            this._spine_free_shouji.active = true;
                            let symbol = this.GetSymbolByIdx(idx);
                            let endNode = cc.vv.gameData.GetBottomScript().getWinLabelNor();
                            let startPos = this._spine_free_shouji.parent.convertToNodeSpaceAR(symbol.node.convertToWorldSpaceAR(cc.v2(0,0)));
                            let endPos = this._spine_free_shouji.parent.convertToNodeSpaceAR(endNode.convertToWorldSpaceAR(cc.v2(0,0)));
                            let dPos = cc.v2(endPos.x-startPos.x, endPos.y-startPos.y);
                            let angle = dPos.signAngle(cc.v2(1,0));
                            this._spine_free_shouji.position = this._spine_free_shouji.parent.convertToNodeSpaceAR(symbol.node.convertToWorldSpaceAR(cc.v2(0,0)));
                            this._spine_free_shouji.angle = -angle * cc.macro.DEG + 90;
                            this._spine_free_shouji.scaleY = Math.abs(dPos.mag())/500;
                            this._spine_free_shouji.getComponent(sp.Skeleton).setAnimation(0,"animation",false);
                            await this.awaitTime(0.6);
                            this._spine_js.active = true;
                            this._spine_js.position = endPos;
                            this._spine_js.getComponent(sp.Skeleton).setAnimation(0,"animation",false);

                            let begin = this._bottomScript.getCurrentWin();
                            let nTotal = winCoin + begin;

                            await this._bottomScript.ShowWin(nTotal,null,begin,null,0.5);
                            break;
                        }
                    }
                }
            }

            sucess()
        })
    },

    // 检查触发免费
    async CheckEnterFreeGame(){
        return new Promise(async (sucess, failed)=>{

            Global.SlotsSoundMgr.playEffect("bell");
            let isFirst = this._gameInfo.freeCnt === this._gameInfo.allFreeCnt;

            for (let id of this._gameInfo.freeResult.freeInfo.idxs) {
                let symbol = this.GetSymbolByIdx(id)
                if(symbol){
                    symbol.playTriggerAnimation(isFirst)
                }
            }
            await this.awaitTime(1.5);

            if( isFirst){ // 首次
                this.Backup();

                await cc.vv.gameData.GetPopupScript().showFirstGainFree();
                cc.vv.gameData.GetPopupScript().playBonusQpAnim();

                await this.awaitTime(1.5);

                this.ShowGameview(true);

                await this.awaitTime(2);
            } else {
                let times = this._gameInfo.freeResult.freeInfo.freeCnt;
                await cc.vv.gameData.GetPopupScript().showAgainGainFree(times);

                await this.awaitTime(1);
            }

            sucess();
        });
    },

    // 免费结束
    async CheckExitFreeGame() {
        return new Promise(async (sucess, failed) => {
            await cc.vv.gameData.GetPopupScript().showEndFree(cc.vv.gameData.GetGameTotalFreeWin());
            cc.vv.gameData.GetPopupScript().playBonusQpAnim();
            await this.awaitTime(1.5);

            this.Resume();
            this.ShowGameview(false);
            Global.SlotsSoundMgr.stopBgm();
            Global.SlotsSoundMgr.playNormalBgm();

            await this.awaitTime(2);
            let nWin = cc.vv.gameData.GetGameTotalFreeWin();
            let nTotal = nWin;
            await new Promise((sucess, failed)=>{
                this.ShowBottomWin(nWin,nTotal,true,sucess)
            });
            sucess();
        })
    },

    // 触发小游戏
    async CheckTriggerBonusGame(){
        return new Promise(async (sucess, failed) => {

            let isSuper = cc.vv.gameData.GetCollectSuper();
            if(isSuper){
                await this.awaitTime(0.5);
                cc.vv.gameData.GetCollectScript().playFullAnim(true);
                Global.SlotsSoundMgr.playEffect("bonus_trigger");
            }else {
                Global.SlotsSoundMgr.playEffect("bell");
            }

            let bonusInfo = cc.vv.gameData.GetBonusInfo();
            for(let key in bonusInfo){
                let idx = bonusInfo[key].idx;
                let symbol = this.GetSymbolByIdx(idx)
                if(symbol){
                    symbol.playTriggerAnimation(true)
                }
            }
            await this.awaitTime(1.5);


            cc.vv.gameData.GetBonusScript().lockJackpot();
            await cc.vv.gameData.GetPopupScript().playTriBonusAnim(isSuper);
            cc.vv.gameData.GetPopupScript().playBonusQpAnim();
            await this.awaitTime(1.5);

            await cc.vv.gameData.GetBonusScript().triBonusGame(sucess)

            for(let key in bonusInfo){
                let idx = bonusInfo[key].idx;
                let symbol = this.GetSymbolByIdx(idx)
                if(symbol){
                    symbol.ShowNormal(true)
                }
            }
        })
    },

    //根据col和row
    getIdxByRowCol(row, col){
        let idx = (this._row - row - 1) * this._col + col +1;
        return idx
    },

    //显示游戏界面：bFree true显示免费模式的界面，false 普通模式
    ShowGameview:function(bFree){
        if(bFree){
            Global.SlotsSoundMgr.playBgm('LoveShotSounds_fsbg')

            let total = cc.vv.gameData.GetTotalFree()
            let rest = cc.vv.gameData.GetFreeTime()

            //显示免费次数
            this._bottomScript.ShowFreeModel(true,total-rest,total)
            let nTotal = cc.vv.gameData.GetFreeWinCoin()
            this._bottomScript.SetWin(nTotal)

            cc.vv.gameData.GetCollectScript().setCollectState(false);
        }
        else{
            this._bottomScript.ShowFreeModel(false)

            cc.vv.gameData.GetCollectScript().setCollectState(true);
        }

        cc.vv.gameData.SetIsFreeGame(bFree);
        this.playCharacterAnim(bFree);

        //可能还需要显示免费背景图
        let normalBg = cc.find("Canvas/safe_node/spr_bg_normal");
        let normalFree = cc.find("Canvas/safe_node/spr_bg_free");
        if(normalFree){ //存在免费游戏背景才执行下面的逻辑
            if(normalBg){
                normalBg.active = !bFree
            }
            normalFree.active = bFree
        }
    },

    // 播放人物动画
    playCharacterAnim(isFree){
        let node = cc.find("Canvas/safe_node/role/renwu");
        let rwSp = node.getComponent(sp.Skeleton)
        // if(isFree){
        //     node.stopAllActions();
        //     node.runAction(cc.repeatForever(cc.sequence(cc.callFunc(()=>{
        //         rwSp.setAnimation(0,"idle",false)
        //         rwSp.addAnimation(0,"skill",false)
        //     }),cc.delayTime(6))));
        // } else {
        //     node.stopAllActions();
        //     node.runAction(cc.repeatForever(cc.sequence(cc.callFunc(()=>{
        //         rwSp.setAnimation(0,"idle",false)
        //         rwSp.addAnimation(0,"skill",false)
        //     }),cc.delayTime(6))));
        // }
        node.stopAllActions();
        rwSp.setAnimation(0,"skill",false)
        rwSp.addAnimation(0,"idle",true)
    },

    awaitTime(time){
        return new Promise((sucess, failed)=>{
            this.scheduleOnce(()=>{
                sucess()
            },time);
        });
    },

});
