cc.Class({
    extends: cc.Component,

    properties: {

    },

    // LIFE-CYCLE CALLBACKS:

    // onLoad () {},

    start () {

    },

    Init(){
        let node_slots =  cc.find("safe_node/slots", this.node);
        this._node_free_again = cc.find("pop_free_again",node_slots);
        this._node_free_again.active = false;

        let node_bonus =  cc.find("safe_node/bonus_slots", this.node);
        this._node_bonus_press= cc.find("node_bonus_press",node_bonus);
        this._node_bonus_press.active = false;

        this._node_popup =  cc.find("safe_node/node_popup", this.node);
        this._node_popup.active = false;
        this._node_free_start = cc.find("pop_free_start",this._node_popup);
        this._node_free_end = cc.find("pop_free_end",this._node_popup);
        this._node_jp_win = cc.find("pop_jp_win",this._node_popup);
        this._node_tri_bonus = cc.find("pop_tri_bonus",this._node_popup);
        this._node_bonus_end= cc.find("node_bonus_end",this._node_popup);
        this._node_free_start.active = false;
        this._node_free_end.active = false;
        this._node_jp_win.active = false;
        this._node_tri_bonus.active = false;
        this._node_bonus_end.active = false;

        this._node_qp = cc.find("safe_node/node_qpAnim", this.node);
        // this._spine_free_qp = cc.find("spine_free_qp", this._node_qp);
        this._spine_bonus_qp = cc.find("spine_bonus_qp", this._node_qp);
        // this._spine_free_qp.active = false;
        this._spine_bonus_qp.active = false;
    },

    // 首次获得免费游戏
    async showFirstGainFree(){
        return new Promise(async (sucess, failed)=>{
            Global.SlotsSoundMgr.stopBgm();
            cc.vv.gameData.GetBottomScript().ShowBtnsByState("moveing_1");
            Global.SlotsSoundMgr.playEffect("mapPopup");

            this._node_popup.active = true;
            this._node_free_start.active = true;
            this._node_free_start.setScale(1);

            let spr = cc.find("spr", this._node_free_start);
            let btn = cc.find("btn_start", this._node_free_start);
            spr.setScale(0);
            btn.setScale(0);

            let spine = cc.find("spine", this._node_free_start);
            spine.getComponent(sp.Skeleton).setAnimation(0, "animation1", false);
            spine.getComponent(sp.Skeleton).addAnimation(0, "animation1_1", true);

            await this.awaitTime(0.3);
            cc.tween(spr).to(0.5, {scale:1},{easing:"backOut"}).start();
            cc.tween(btn).to(0.5, {scale:1},{easing:"backOut"}).start();

            await this.awaitTime(0.3);

            btn.getComponent(cc.Button).interactable = true;
            btn.off("click");
            let self = this;
            let func = ()=>{
                btn.getComponent(cc.Button).interactable = false;

                Global.SlotsSoundMgr.playEffect("mapend");
                cc.tween(this._node_free_start).to(0.7,{scale:0}, {easing:"backIn"})
                    .call(()=>{
                        self._node_popup.active = false;
                        self._node_free_start.active = false;
                        sucess();
                    })
                    .start();
            }

            cc.vv.gameData.checkAutoPlay(btn, func);
            btn.on("click", ()=>{
                btn.stopAllActions();
                func();
            })
        });
    },

    // 再次获得免费
    showAgainGainFree(times){
        return new Promise(async (sucess, failed)=> {
            Global.SlotsSoundMgr.playEffect("dialog_fg_retrigger");

            // this._node_popup.active = true;
            this._node_free_again.active = true;
            let node_pop = cc.find("node_pop", this._node_free_again);
            node_pop.setScale(1);

            let lbl_num = cc.find("lbl_num",node_pop);
            lbl_num.getComponent(cc.Label).string = times;
            lbl_num.setScale(0);

            let spine = cc.find("spine",node_pop);
            spine.getComponent(sp.Skeleton).setAnimation(0,"animation1",false);
            spine.getComponent(sp.Skeleton).addAnimation(0,"animation2",true);

            await this.awaitTime(0.5);
            cc.tween(lbl_num).to(0.5, {scale:1}, {easing:"backOut"}).start()

            await this.awaitTime(1.5);

            Global.SlotsSoundMgr.playEffect("mapPopup");
            cc.tween(node_pop).to(0.7,{scale:0}, {easing:"backIn"}).start();

            await this.awaitTime(0.7);
            // this._node_popup.active = false;
            this._node_free_again.active = false;
            sucess()
        });
    },

    // 免费结束
    showEndFree(winCoin){
        return new Promise(async (sucess, failed)=> {
            Global.SlotsSoundMgr.stopBgm();
            cc.vv.gameData.GetBottomScript().ShowBtnsByState("moveing_1");
            Global.SlotsSoundMgr.playEffect("sound_LuckyDollar_bonus_over");

            this._node_popup.active = true;
            this._node_free_end.active = true;
            this._node_free_end.setScale(1);

            let lbl_winCoin = cc.find("lbl_winCoin",this._node_free_end);
            Global.doRoallNumEff(lbl_winCoin,0,winCoin, 1.5,null,null,0,true);

            let btn = cc.find("btn_collect",this._node_free_end);
            btn.setScale(0);

            let spine = cc.find("spine", this._node_free_end);
            spine.getComponent(sp.Skeleton).setAnimation(0, "animation2", false);
            spine.getComponent(sp.Skeleton).addAnimation(0, "animation2_1", true);

            await this.awaitTime(0.3);
            cc.tween(btn).to(0.5, {scale:1},{easing:"backOut"}).start();

            await this.awaitTime(0.3);

            btn.getComponent(cc.Button).interactable = true;
            btn.off("click");
            let self = this;
            let func = ()=>{
                btn.getComponent(cc.Button).interactable = false;
                lbl_winCoin.stopAllActions();
                let delayT = 0;
                if(Global.FormatCommaNumToNum(lbl_winCoin.getComponent(cc.Label).string) < winCoin){
                    lbl_winCoin.getComponent(cc.Label).string = Global.FormatNumToComma(winCoin);
                    delayT += 0.3;
                }

                Global.SlotsSoundMgr.playEffect("mapend");
                cc.tween(this._node_free_end)
                    .delay(delayT)
                    .to(0.7,{scale:0}, {easing:"backIn"})
                    .call(()=>{
                        self._node_popup.active = false;
                        self._node_free_end.active = false;
                        sucess();
                    })
                    .start();
            }
            cc.vv.gameData.checkAutoPlay(btn, func);
            btn.on("click", ()=>{
                btn.stopAllActions();
                func();
            })
        });
    },

    // 免费清屏动画
    // playFreeQpAnim(){
    //     let self = this;
    //     Global.SlotsSoundMgr.playEffect("music_LoveShot_CashRush_Trigger");
    //     this._spine_free_qp.active = true;
    //     this._spine_free_qp.getComponent(sp.Skeleton).setAnimation(0,"animation", false);
    //     this._spine_free_qp.getComponent(sp.Skeleton).setCompleteListener(()=>{
    //         self._spine_free_qp.active = false;
    //     })
    // },


    // 赢得奖池
    showWinJp(winCoin, jp){
        return new Promise(async (sucess, failed)=> {
            Global.SlotsSoundMgr.playEffect("dialog_trigger_JP");

            this._node_popup.active = true;
            this._node_jp_win.active = true;
            this._node_jp_win.setScale(1);

            let lbl_winCoin = cc.find("lbl_winCoin",this._node_jp_win);
            Global.doRoallNumEff(lbl_winCoin,0,winCoin, 1.5,null,null,0,true);

            let btn = cc.find("btn_collect",this._node_jp_win);
            btn.setScale(0);

            let spine = cc.find("spine", this._node_jp_win);
            let animType = 5-jp;
            spine.getComponent(sp.Skeleton).setAnimation(0, "animation"+animType+"_1", false);
            spine.getComponent(sp.Skeleton).addAnimation(0, "animation"+animType+"_2", true);

            await this.awaitTime(0.3);
            cc.tween(btn).to(0.5, {scale:1},{easing:"backOut"}).start();

            cc.tween(this._node_jp_win)
                .delay(5)
                .call(()=>{
                    btn.off("click");
                    Global.SlotsSoundMgr.playEffect("popup_out");
                })
                .to(0.7,{scale:0}, {easing:"backIn"})
                .call(()=>{
                    self._node_popup.active = false;
                    self._node_jp_win.active = false;
                    sucess();
                }).start()

            await this.awaitTime(0.3);

            btn.getComponent(cc.Button).interactable = true;
            btn.off("click");
            let self = this;
            let func = ()=>{
                Global.SlotsSoundMgr.playEffect("popup_out");

                btn.getComponent(cc.Button).interactable = false;
                this._node_jp_win.cleanup();
                cc.tween(this._node_jp_win).to(0.7,{scale:0}, {easing:"backIn"})
                    .call(()=>{
                        self._node_popup.active = false;
                        self._node_jp_win.active = false;
                        sucess();
                    })
                    .start();
            }
            cc.vv.gameData.checkAutoPlay(btn, func);
            btn.on("click", ()=>{
                btn.stopAllActions();
                func();
            })
        });
    },

    // 触发bonus游戏
    playTriBonusAnim(isSuper){
        return new Promise(async (sucess, failed)=> {
            Global.SlotsSoundMgr.stopBgm();
            this._node_popup.active = true;
            this._node_tri_bonus.active = true;

            let spine_super = cc.find("spine_super", this._node_tri_bonus);
            let spine_normal = cc.find("spine_normal", this._node_tri_bonus);

            spine_super.active = isSuper;
            spine_normal.active = !isSuper;

            let self = this;
            if(isSuper){
                Global.SlotsSoundMgr.playEffect("sound_LuckyDollar_freespin_start");
                spine_super.getComponent(sp.Skeleton).setAnimation(0,"animation",false);
                await this.awaitTime(3);
                Global.SlotsSoundMgr.playEffect("bgbgmend");
                spine_super.getComponent(sp.Skeleton).setCompleteListener(()=>{
                    self._node_popup.active = false;
                    self._node_tri_bonus.active = false;
                    sucess();
                })
            } else {
                Global.SlotsSoundMgr.playEffect("music_LoveShot_over_fs");
                spine_normal.getComponent(sp.Skeleton).setAnimation(0,"animation1",false);
                spine_normal.getComponent(sp.Skeleton).addAnimation(0,"animation2",false);
                let entry = spine_normal.getComponent(sp.Skeleton).addAnimation(0,"animation3",false);
                spine_normal.getComponent(sp.Skeleton).setTrackStartListener(entry,()=>{
                    Global.SlotsSoundMgr.playEffect("bgbgmend");
                });
                spine_normal.getComponent(sp.Skeleton).setTrackCompleteListener(entry,()=>{
                    self._node_popup.active = false;
                    self._node_tri_bonus.active = false;
                    sucess();
                })
            }
        });
    },

    // 小游戏press unlockNum-未锁的总条数
    showBonusPress(isSuper, unlockNum){
        return new Promise(async (sucess, failed)=> {
            // Global.SlotsSoundMgr.playEffect("");

            // this._node_popup.active = true;
            this._node_bonus_press.active = true;
            let node_pop = cc.find("node_pop", this._node_bonus_press);
            let mask = cc.find("mask", this._node_bonus_press);
            node_pop.setScale(1);

            var cfg = cc.vv.gameData.getGameCfg();
            node_pop.height = unlockNum * cfg.symbolSize.height;
            mask.height = unlockNum * cfg.symbolSize.height;

            let spine = cc.find("spine",node_pop);
            if (isSuper){
                spine.getComponent(sp.Skeleton).setAnimation(0, "animation1", false);
                spine.getComponent(sp.Skeleton).addAnimation(0, "animation2", true);
            } else {
                spine.getComponent(sp.Skeleton).setAnimation(0, "animation3", false);
                spine.getComponent(sp.Skeleton).addAnimation(0, "animation4", true);
            }

            await this.awaitTime(0.5);

            let btn_press = cc.find("btn_press",node_pop);
            btn_press.getComponent(cc.Button).interactable = true;
            btn_press.off("click");
            let self = this;
            let func = async ()=>{
                // Global.SlotsSoundMgr.playEffect("popup_out");

                btn_press.getComponent(cc.Button).interactable = false;

                cc.tween(node_pop).to(0.7,{scale:0}, {easing:"backIn"}).start()

                await self.awaitTime(0.7);
                // self._node_popup.active = false;
                self._node_bonus_press.active = false;
                sucess()
            }
            cc.vv.gameData.checkAutoPlay(btn_press, func);
            btn_press.on("click", async()=>{
                btn_press.stopAllActions();
                await func();
            })
        })
    },


    // bonus结束
    showBonusWin(winCoin){
        return new Promise(async (sucess, failed)=> {
            Global.SlotsSoundMgr.stopBgm();
            cc.vv.gameData.GetBottomScript().ShowBtnsByState("moveing_1");
            Global.SlotsSoundMgr.playEffect("sound_LuckyDollar_freespin_over");

            this._node_popup.active = true;
            this._node_bonus_end.active = true;
            this._node_bonus_end.setScale(1);

            let lbl_winCoin = cc.find("lbl_winCoin",this._node_bonus_end);
            Global.doRoallNumEff(lbl_winCoin,0,winCoin, 1.5,null,null,0,true);

            let btn = cc.find("btn_collect",this._node_bonus_end);
            btn.setScale(0);

            let spine = cc.find("spine", this._node_bonus_end);
            spine.getComponent(sp.Skeleton).setAnimation(0, "animation1", false);
            spine.getComponent(sp.Skeleton).addAnimation(0, "animation2", true);

            await this.awaitTime(0.3);
            cc.tween(btn).to(0.5, {scale:1},{easing:"backOut"}).start();

            await this.awaitTime(0.3);

            btn.getComponent(cc.Button).interactable = true;
            btn.off("click");
            let self = this;
            let func = ()=>{
                Global.SlotsSoundMgr.playEffect("bgend");
                btn.getComponent(cc.Button).interactable = false;

                lbl_winCoin.stopAllActions();
                let delayT = 0;
                if(Global.FormatCommaNumToNum(lbl_winCoin.getComponent(cc.Label).string) < winCoin){
                    lbl_winCoin.getComponent(cc.Label).string = Global.FormatNumToComma(winCoin);
                    delayT += 0.3;
                }

                cc.tween(this._node_bonus_end)
                    .delay(delayT)
                    .to(0.7,{scale:0}, {easing:"backIn"})
                    .call(()=>{
                        self._node_popup.active = false;
                        self._node_bonus_end.active = false;
                        sucess();
                    })
                    .start();
            }
            cc.vv.gameData.checkAutoPlay(btn, func);
            btn.on("click", ()=>{
                btn.stopAllActions();
                func();
            })
        });
    },

    // bonus清屏动画
    playBonusQpAnim(){
        let self = this;
        Global.SlotsSoundMgr.playEffect("music_LoveShot_rush_CollectGame_Trigger");
        this._spine_bonus_qp.active = true;
        this._spine_bonus_qp.getComponent(sp.Skeleton).setAnimation(0,"idle2", false);
        this._spine_bonus_qp.getComponent(sp.Skeleton).setCompleteListener(()=>{
            self._spine_bonus_qp.active = false;
        })
    },

    awaitTime(time){
        return new Promise((sucess, failed)=>{
            this.scheduleOnce(()=>{
                sucess()
            },time);
        });
    },
    // update (dt) {},
});
