// Learn cc.Class:
//  - https://docs.cocos.com/creator/manual/en/scripting/class.html
// Learn Attribute:
//  - https://docs.cocos.com/creator/manual/en/scripting/reference/attributes.html
// Learn life-cycle callbacks:
//  - https://docs.cocos.com/creator/manual/en/scripting/life-cycle-callbacks.html

cc.Class({
    extends: cc.Component,

    properties: {
        _exitCallBack:null,

        _curTimes:3,   // 当前剩余次数

        _reels:[],  //卷轴脚本对象
        _shelterList:[],    // 横条遮罩
        _bonusPoolList:[],   // 奖池节点
    },

    // LIFE-CYCLE CALLBACKS:

    // onLoad () {},

    start () {

    },

    Init(){
        this.initBonusNode();

        this._topScript = cc.vv.gameData.GetTopScript();
        this._bottomScript = cc.vv.gameData.GetBottomScript();

        this._cfg = cc.vv.gameData.getGameCfg();
        this._col = this._cfg.bonus_col;
        this._row = this._cfg.bonus_row;

        this.createReels(this._col, this._row);

        this.initBonusUI();
    },

    //创建卷轴
    createReels:function(col, row){
        let reelCmp = this._cfg.scripts.Reels;
        for (let i = 0; i < col; i++) {
            let node = cc.find("reels/reel" + (i+1),this._bonus_slots);
            let scp = node.addComponent("GodnessOfLove_BonusReel");
            scp.Init(i,1,row,this._topAniNode);
            this._reels.push(scp)
        }
    },


    // 初始化节点
    initBonusNode(){

        this._normal_slots = cc.find("safe_node/slots", this.node);
        this._bg_bonus = cc.find("safe_node/spr_bg_bonus", this.node);
        this._bonus_slots = cc.find("safe_node/bonus_slots", this.node);

        this._topAniNode = cc.find("top_ani",this._bonus_slots);
        this._node_reels = cc.find("reels", this._bonus_slots);

        this._reels_bg_1 = cc.find("reels_bg_1", this._bonus_slots);
        this._reels_bg_2 = cc.find("reels_bg_2", this._bonus_slots);
        this._spine_hengtiao = cc.find("spine_hengtiao", this._bonus_slots);

        this._reels_bg = cc.find("reels_bg", this._bonus_slots);
        this._node_col = cc.find("mask/node_col", this._reels_bg);
        this._node_row_left = cc.find("mask/node_row_left", this._reels_bg);
        this._node_row_right = cc.find("mask/node_row_right", this._reels_bg);

        this._frame_top = cc.find("frame_top", this._bonus_slots);

        this._node_tit = cc.find("node_tit", this._frame_top);
        this._par_left = cc.find("par_left", this._frame_top);
        this._par_right = cc.find("par_right", this._frame_top);
        this._shelterList.push(cc.find("shelter_1", this._frame_top));
        this._shelterList.push(cc.find("shelter_2", this._frame_top));
        this._shelterList.push(cc.find("shelter_3", this._frame_top));
        this._shelterList.push(cc.find("shelter_4", this._frame_top));

        this._spine_jsKuang = cc.find("spine_jsKuang", this._bonus_slots);
        this._spine_shouji = cc.find("spine_bonus_shouji", this._bonus_slots.parent);
        this._spine_js = cc.find("spine_bonus_js", this._bonus_slots.parent);
    },

    // 初始化节点状态
    initBonusUI(){
        this._normal_slots.active = true;
        this._bg_bonus.active = false;
        this._bonus_slots.active = false;

        this._reels_bg_1.active = false;
        this._reels_bg_2.active = false;
        this._spine_hengtiao.active = false;

        this._reels_bg.active = false;

        this.setLineState(this._node_col, false);
        this.setLineState(this._node_row_left, false);
        this.setLineState(this._node_row_right, false);

        this._node_tit.active = false;
        for(let i = 0; i < this._shelterList.length; i++){
            this._shelterList[i].active = false;
        }

        this._par_left.active = false;
        this._par_right.active = false;
        this._node_reels.active = false;

        this._spine_jsKuang.active = false;
        this._spine_shouji.active = false;
        this._spine_js.active = false;
    },

    setLineState(parentNode, bShow){
        for (let i = 0; i < parentNode.childrenCount; i++){
            parentNode.children[i].active = bShow;
        }
    },

    playBonusBgm(){
        let isSuper = cc.vv.gameData.GetCollectSuper();
        if (isSuper){
            Global.SlotsSoundMgr.playBgm('LoveShotSounds_Rsbg');
        } else {
            Global.SlotsSoundMgr.playBgm('music_LoveShot_mapGameBG');
        }
    },

    // 触发
    async triBonusGame(success){
        this._exitCallBack = success;

        this.playBonusBgm();

        this._bottomScript.SetWin();

        for (let col = 0; col < this._col; col++){
            for (let row = 0; row < this._row; row++){
                this._reels[col].setHolderPlay(row, true);
            }
        }

        // this.lockJackpot();
        await this.playTriAnim();

        cc.vv.gameData.SetIsBonusGame(true);
        this.sendNextRound();
    },

    // 触发动画
    playTriAnim(){
        return new Promise(async (sucess, failed)=> {

            // 1.初始大小显示
            this._normal_slots.active = false;
            this._bg_bonus.active = true;
            this._bonus_slots.active = true;

            this._reels_bg_1.active = true;
            await this.awaitTime(1);

            Global.SlotsSoundMgr.playEffect("reel_raise");

            // 2.两个小背景框合并为一个大背景框
            this._reels_bg_2.active = true;
            this._reels_bg_2.position = cc.v2(750,120);
            cc.tween(this._reels_bg_2)
                .to(0.8,{position:cc.v2(0,120)})
                .to(0.8,{position:cc.v2(0, this._reels_bg_1.y + this._reels_bg_1.height)},{easing:"backInOut"})
                .start()

            await this.awaitTime(1.3);

            cc.tween(cc.find("spr_up",this._reels_bg_1)).to(0.3,{opacity:0}).start()
            cc.tween(cc.find("spr_down",this._reels_bg_2)).to(0.3,{opacity:0}).start()

            this._spine_hengtiao.active = true;
            this._spine_hengtiao.getComponent(sp.Skeleton).setAnimation(0,"animation", false);

            await this.awaitTime(0.5)
            this._reels_bg.active = true;
            cc.find("spr_up",this._reels_bg_1).opacity = 255;
            cc.find("spr_down",this._reels_bg_2).opacity = 255;
            this._reels_bg_1.active = false;
            this._reels_bg_2.active = false;

            // 3.竖条隔断上长到顶部，底部从中间长到两头 （同时）
            let awaitT3 = 1.4;
            for(let i = 0; i < this._node_col.childrenCount; i++){
                let node = this._node_col.children[i];
                node.active = true;
                node.y = -400;
                if(node.name === "par"){
                    node.getComponent(cc.ParticleSystem).resetSystem();
                }
                cc.tween(node).to(awaitT3, {position:cc.v2(node.x,400)})
                    .call(()=>{
                        if(node.name === "par"){node.active = false;}})
                    .start();
            }

            this._par_left.active = true;
            this._par_left.position = cc.v2(0,-400);
            this._par_left.getComponent(cc.ParticleSystem).resetSystem();
            this._par_right.active = true;
            this._par_right.position = cc.v2(0,-400);
            this._par_right.getComponent(cc.ParticleSystem).resetSystem();
            cc.tween(this._par_left).to(awaitT3, {position:cc.v2(-333,-400)}).start();
            cc.tween(this._par_right).to(awaitT3, {position:cc.v2(333,-400)}).start();

            await this.awaitTime(awaitT3);

            // 4.246行从左往右，1357行从右往左，左右两列长到顶（同时）
            let awaitT4 = 1.4;
            for(let i = 0; i < this._node_row_left.childrenCount; i++){
                let node = this._node_row_left.children[i];
                node.active = true;
                node.x = -333;
                if(node.name === "par"){
                    node.getComponent(cc.ParticleSystem).resetSystem();
                }
                cc.tween(node).to(awaitT4, {position:cc.v2(333,node.y)})
                    .call(()=>{
                        if(node.name === "par"){node.active = false;}})
                    .start();
            }
            for(let i = 0; i < this._node_row_right.childrenCount; i++){
                let node = this._node_row_right.children[i];
                node.active = true;
                node.x = 333;
                if(node.name === "par"){
                    node.getComponent(cc.ParticleSystem).resetSystem();
                }
                cc.tween(node).to(awaitT4, {position:cc.v2(-333,node.y)})
                    .call(()=>{
                        if(node.name === "par"){node.active = false;}})
                    .start();
            }
            cc.tween(this._par_left).to(awaitT4, {position:cc.v2(-333,400)}).start();
            cc.tween(this._par_right).to(awaitT4, {position:cc.v2(333,400)}).start();

            await this.awaitTime(awaitT4);

            // 5.顶部从两侧到中间
            let awaitT5 = 0.7;
            cc.tween(this._par_left).to(awaitT5, {position:cc.v2(0,400)})
                .call(()=>{this._par_left.active = false;})
                .start();
            cc.tween(this._par_right).to(awaitT5, {position:cc.v2(0,400)})
                .call(()=>{this._par_right.active = false;})
                .start();
            await this.awaitTime(awaitT5);


            // 6.3spins 弹出，背景、所有reels显示
            let awaitT6 = 0.5;
            this._node_tit.active = true;
            this._node_tit.setScale(0);
            Global.SlotsSoundMgr.playEffect("bonus_land");
            cc.tween(this._node_tit).to(awaitT6, {scale:1}, { easing: 'backOut'}).start()
            this._curTimes = 3;
            this.setTitleNum(this._curTimes);

            this._node_reels.active = true;
            this.initAllSymbol(true);

            await this.awaitTime(awaitT6);

            // 7.4个锁条从上往下依次出现,先全展示，再刷新次数
            let total = this.getCurUnlockNum();
            let bonusUnlockList = cc.vv.gameData.GetBonusCfg();
            for (let i = 0; i < this._shelterList.length; i++){
                Global.SlotsSoundMgr.playEffect("lock_show");
                this._shelterList[i].active = true;
                cc.find("lbl_num",this._shelterList[i]).getComponent(cc.Label).string = bonusUnlockList[i];
                cc.find("spine_bao",this._shelterList[i]).active = false;
                await this.awaitTime(0.3);
            }
            await this.hideShelter();
            await this.awaitTime(0.3);

            // 8.boost图标弹动画
            await this.playBounceAnim();
            await this.awaitTime(1);

            // 9.弹出press按钮,点击press,面板收回，开始旋转
            let isSuper = cc.vv.gameData.GetCollectSuper();
            let unlockNum = cc.vv.gameData.GetBonusRow().after;
            await cc.vv.gameData.GetPopupScript().showBonusPress(isSuper, unlockNum);

            sucess();
        })
    },

    // 断线
    async enterBonusGame(success){
        this._exitCallBack = success;

        this.playBonusBgm();

        this.lockJackpot();
        this.showEnterState();

        await this.awaitTime(2);

        cc.vv.gameData.SetIsBonusGame(true);
        this.sendNextRound();
    },

    showEnterState(){
        // 显示所有节点状态
        this._normal_slots.active = false;
        this._bg_bonus.active = true;
        this._bonus_slots.active = true;

        for(let i = 0; i < this._node_col.childrenCount; i++) {
            if(this._node_col.children[i].name === "par"){
                this._node_col.children[i].active = false;
            }else {
                this._node_col.children[i].active = true;
                this._node_col.children[i].position = cc.v2(this._node_col.children[i].x, 400);
            }
        }
        for(let i = 0; i < this._node_row_left.childrenCount; i++) {
            if(this._node_row_left.children[i].name === "par"){
                this._node_row_left.children[i].active = false;
            }else {
                this._node_row_left.children[i].active = true;
                this._node_row_left.children[i].position = cc.v2(333, this._node_row_left.children[i].y);
            }
        }
        for(let i = 0; i < this._node_row_right.childrenCount; i++) {
            if(this._node_row_right.children[i].name === "par"){
                this._node_row_right.children[i].active = false;
            }else {
                this._node_row_right.children[i].active = true;
                this._node_row_right.children[i].position = cc.v2(-333, this._node_row_right.children[i].y);
            }
        }

        this._node_tit.active = true;
        this._node_tit.setScale(1);
        this._curTimes = cc.vv.gameData.GetBonusRestNum();
        this.setTitleNum(this._curTimes);

        this._reels_bg.active = true;
        this._node_reels.active = true;
        this.initAllSymbol(false);

        // 显示遮罩层状态
        let total = this.getCurUnlockNum();
        let bonusUnlockList = cc.vv.gameData.GetBonusCfg();
        for (let i = 0; i < this._shelterList.length; i++){
            if(total < bonusUnlockList[i]){
                this._shelterList[i].active = true;
                cc.find("lbl_num",this._shelterList[i]).getComponent(cc.Label).string = bonusUnlockList[i] - total;
            } else {
                this._shelterList[i].active = false;
            }
        }
    },

    async exitBonusGame(){
        if(cc.vv.gameData.GetCollectSuper()){
            cc.vv.gameData.SetCollectCurNum(0);
            cc.vv.gameData.GetCollectScript().initItems();
        }

        cc.vv.gameData.GetPopupScript().playBonusQpAnim();
        await this.awaitTime(1.5)

        this.resetJackpot()
        this.initBonusUI();
        cc.vv.gameData.SetIsBonusGame(false);
        await this.awaitTime(1.5)

        let nWin = cc.vv.gameData.GetBonusWinCoin();
        await new Promise((sucess, failed)=>{
            // cc.vv.gameData.AddCoin(nWin);
            cc.vv.gameData.GetSlotsScript().ShowBottomWin(nWin,nWin,true,sucess)
        });

        if(this._exitCallBack){
            this._exitCallBack();
            this._exitCallBack = null;
        }

        Global.SlotsSoundMgr.stopBgm();
        Global.SlotsSoundMgr.playNormalBgm();   // 只会普通游戏中bonus游戏
    },

    // 设置标题次数
    setTitleNum(num){
        cc.find("node_3",this._node_tit).active = num === 3;
        cc.find("node_2",this._node_tit).active = num === 2;
        cc.find("node_1",this._node_tit).active = num === 1;
        cc.find("node_0",this._node_tit).active = num === 0;
        cc.find("node_complete",this._node_tit).active = num < 0;

        let spine = cc.find("spine",this._node_tit);
        if (this._curTimes < num && num === 3){
            spine.active = true;
            spine.getComponent(sp.Skeleton).setAnimation(0, "animation", false);
        }else {
            spine.active = false;
        }

        if(num < 0){
            Global.SlotsSoundMgr.playEffect("respin_end");
        }

        this._curTimes = num;
    },

    // 初始展示的所有symbol
    initAllSymbol(isTri){
        let result = cc.vv.gameData.GetBonusResult();

        let reelData = [];
        for (let i = 0; i < this._col*this._row; i++) {
            let info = {};
            info.sid = 16;
            info.data = {};
            reelData.push(info)
        }
        if(isTri){
            //  触发那一局，使用初始数据
            let redData = result[0].red;
            let boostData = result[0].boost;
            for (let key in redData.data){
                let idx_k = Number(key.substring("idx_".length));
                reelData[idx_k-1].sid = 5;
                reelData[idx_k-1].data = redData.data[key];
            }
            for (let i = 0; i < boostData.idxs.length; i++){
                let idx = boostData.idxs[i];
                reelData[idx - 1].sid = 6;
            }
        } else {
            // 断线那一局，使用boost弹完后的数据，
            let redData = result[result.length - 1].red;
            let boostData = result[result.length - 1].boost;
            for (let key in redData.data){
                let idx_k = Number(key.substring("idx_".length));
                if(redData.data[key].color === 1){
                    reelData[idx_k-1].sid = 5;
                }else {
                    reelData[idx_k-1].sid = 601;
                }

                reelData[idx_k-1].data = redData.data[key];
            }
        }

        // 对所有图标节点进行赋值
        for(let i = 0; i < this._col*this._row; i++){
            let symbol = this.GetSymbolByIdx(i+1);

            if(reelData[i].sid === 16){
                let cfg = cc.vv.gameData.getGameCfg();
                let randIdx = Global.random(1,cfg.randomSymbolsBonus.length);
                reelData[i].sid = cfg.randomSymbolsBonus[randIdx-1];
                symbol.ShowById(reelData[i].sid)
            } else {
                symbol.ShowById(reelData[i].sid, reelData[i].data);
                symbol.playBonusIdleAnim();
                this._reels[this.getColByIdx(i+1)].setHolderPlay(this.getRowByIdx(i+1), false);
            }
        }
    },

    // boost图标弹动画
    async playBounceAnim(){
        return new Promise(async (sucess, failed)=> {
            let result = cc.vv.gameData.GetBonusResult();

            let spine_move = cc.find("spine_move", this._bonus_slots);
            let par_move = cc.find("par_move", this._bonus_slots);
            let spine_move_end = cc.find("spine_move_end", this._bonus_slots);

            if(result && result.length > 1){
                for(let i = 1; i < result.length; i++){
                    await this.awaitTime(0.4);
                    let data = result[i];

                    let traceIdxs = data.boost.traceIdxs;
                    let showIdx = data.boost.showIdx;

                    let startPos = this._bonus_slots.convertToNodeSpaceAR(this.GetSymbolByIdx(showIdx).node.convertToWorldSpaceAR(cc.v2(0,0)));
                    spine_move.position = startPos;
                    par_move.position = startPos;

                    traceIdxs.push(showIdx);
                    for(let j = 0; j < traceIdxs.length; j++){
                        let idx = traceIdxs[j];

                        let endSym = this.GetSymbolByIdx(idx);
                        let endPos = this._bonus_slots.convertToNodeSpaceAR(endSym.node.convertToWorldSpaceAR(cc.v2(0,0)));

                        spine_move.active = true;
                        par_move.active = true;
                        par_move.getComponent(cc.ParticleSystem).resetSystem();

                        Global.SlotsSoundMgr.playEffect("bonus_fly");

                        let moveT = 0.3;
                        cc.tween(spine_move)
                            .to(moveT,{position:endPos})
                            .call(()=>{
                                spine_move.active = false;
                            })
                            .start()
                        cc.tween(par_move)
                            .to(moveT,{position:endPos})
                            .call(()=>{
                                par_move.active = false;
                            })
                            .start()

                        await this.awaitTime(moveT);
                        spine_move_end.active = true;
                        spine_move_end.position = endPos;
                        spine_move_end.getComponent(sp.Skeleton).setAnimation(0,"animation",false);

                        for(let key in data.red.data){
                            let idx_k = Number(key.substring("idx_".length));
                            if(idx === idx_k) {
                                endSym.ShowById(601, data.red.data[key]);
                                endSym.playBonusIdleAnim();
                            }
                        }

                        await this.awaitTime(0.1);
                        Global.SlotsSoundMgr.stopEffectByName("bonus_fly");
                    }

                }
            }
            sucess();
        });
    },

    //点击旋转按钮调用
    StartMove:function(){
        this._bStopRightnow = null
        this._gameInfo = null

        //top状态更新
        // this._topScript.StartMove()

        //清理数据
        // cc.vv.gameData.ClearOneRoundData()

        //每列转起来
        this.MoveReels(this._reels)

        //设置停止时间
        //就是从开始旋转，如果多少秒会开始停止
        this._stopTime = this.GetStopTime()

        this._curTimes -= 1;
        this.setTitleNum(this._curTimes);
        Global.SlotsSoundMgr.playEffect("");
    },

    //实际旋转起来的列，有时候需要1，2，4列转，
    //即最后停止下来的不是最后一列的序号，所以需要记录最后一列的序号
    //arry=[this._reels[0],this._reels[1],this._reels[4]]
    MoveReels:function(arry){
        this.moveReelLastIdx = -1
        for(let i = 0; i < arry.length; i++){
            let item = arry[i]
            item.StartMove()
            let idx = item.GetReelIdx()
            if(idx> this.moveReelLastIdx){
                this.moveReelLastIdx = idx
            }
        }
    },


    //点击停止按钮调用
    StopMove:function(){
        this._bStopRightnow = true
        this._bottomScript.ShowBtnsByState("moveing_1")

        this._stopTime = -1
        for(let i = 0; i < this._reels.length; i++ ){
            let item = this._reels[i]
            let reelStopInterv = 0 //立即停止
            item.StopMove(reelStopInterv)
            item.StopMoveRightNow()
        }
    },


    //收到旋转结果
    //gameData模块收到数据后，转发到此处
    onMsgSpine:function(msg){
        this._gameInfo = msg
        let cards = msg.resultCards
        this.SetSlotsResult(cards)
    },

    //处理结果给reel设置结果
    SetSlotsResult:function(){
        //把结果按卷轴结果整理
        // let acRow = cards.length / this._col;
        let reelResults = [];

        let result = cc.vv.gameData.GetBonusResult();

        let reelData = [];
        for (let i = 0; i < this._col*this._row; i++) {
            let info = {};
            let cfg = cc.vv.gameData.getGameCfg();
            let randIdx = Global.random(1,cfg.randomSymbolsBonus.length);
            info.sid = cfg.randomSymbolsBonus[randIdx-1];
            info.data = {};
            reelData.push(info)
        }

        let redData = result[0].red;
        let boostData = result[0].boost;
        for (let key in redData.data){
            let idx_k = Number(key.substring("idx_".length));
            reelData[idx_k-1].sid = 5;
            reelData[idx_k-1].data = redData.data[key];
        }
        for (let i = 0; i < boostData.idxs.length; i++){
            let idx = boostData.idxs[i];
            reelData[idx - 1].sid = 6;
        }

        for (let i = 0; i < reelData.length; i++){
            let col = i % this._col;
            if(!reelResults[col]) reelResults[col] = [];
            reelResults[col].unshift(reelData[i]);
        }

        for(let i = 0; i < this._reels.length; i++){
            let item = this._reels[i]
            let reelRes = reelResults[i]
            item.SetResult(reelRes)
        }
    },

    //回弹动作最低点
    OnReelBounsActionDeep(colIdx){
        Global.SlotsSoundMgr.playEffect("reel_stop");
    },

    // 单列停止
    OnReelBounsActionEnd(colIdx){
        for(let row = 0; row < this._row; row++){
            let isPlay = this._reels[colIdx].getHolderPlay(row);

            if(isPlay){
                let symScp = this._reels[colIdx].GetSymbolByRow(row);
                let id = symScp.GetShowId();

                if(id === 5 || id === 6){
                    Global.SlotsSoundMgr.playEffect("bonus_land");

                    symScp.playBonusStopAnim();

                    this._reels[colIdx].setHolderPlay(row, false);
                }
            }
        }
    },

    //全部列都停止了
    //处理停下后的中奖情况，这里多数情况需要根据自己的逻辑来处理
    async OnSpinEnd(){

        // await this.awaitTime(2);

        let restNum = cc.vv.gameData.GetBonusRestNum();

        this.setTitleNum(restNum);
        if(restNum === 3){
            // Global.SlotsSoundMgr.playEffect("bonus_remainingReset");

            // 有新增图标
            await this.hideShelter();
        }


        // boost图标弹动画
        await this.playBounceAnim();

        await this.awaitTime(1)


        if(restNum === 0){
            await this.playCompleteAnim();

            this.exitBonusGame();
        } else {

            this.sendNextRound();
        }

    },

    // 当前解锁行的图标个数
    getCurUnlockNum(){
        let unlockRow = cc.vv.gameData.GetBonusRow().after;

        let total = 0;
        for(let col = 0; col < this._col; col++){
            for (let row = 0; row < unlockRow; row++){
                let sym = this._reels[col].GetSymbolByRow(row);
                let id = sym.GetShowId();

                if(id === 5 || id === 6 || id === 601){
                    total += 1;
                }
            }
        }

        return total;
    },

    // 隐藏遮罩条
    hideShelter(){
        return new Promise(async (sucess, failed)=> {
            let bonusUnlockList = cc.vv.gameData.GetBonusCfg();

            let total = this.getCurUnlockNum();
            for (let i = this._shelterList.length - 1; i >= 0; i--) {
                if (this._shelterList[i].active) {
                    let rest = bonusUnlockList[i] - total;
                    cc.find("lbl_num", this._shelterList[i]).getComponent(cc.Label).string = Math.max(0,rest);

                    cc.find("spine_bao", this._shelterList[i]).active = true;
                    cc.find("spine_bao", this._shelterList[i]).getComponent(sp.Skeleton).setAnimation(0, "animation1", false);
                }
            }
            await this.awaitTime(0.5)


            for (let i = this._shelterList.length - 1; i >= 0; i--){

                if(total >= bonusUnlockList[i]){
                    if(this._shelterList[i].active){
                        Global.SlotsSoundMgr.playEffect("reel_unlock");
                        let self = this;
                        this._shelterList[i].active = false;
                        let spine = cc.find("unlock_"+(i+1),this._frame_top);
                        spine.active = true;
                        spine.getComponent(sp.Skeleton).setAnimation(0,"animation",false);
                        spine.getComponent(sp.Skeleton).setCompleteListener(()=>{

                            spine.active = false
                        });
                        await this.awaitTime(0.5)
                    }
                }
            }
            sucess()
        })
    },

    // 结算时动画播放
    async playBonusBombAnim(sym){
        if(sym){
            sym.playBonusBombAnim(true);
            sym.playBonusEndAnim();
            await this.awaitTime(0.5);
            sym.playBonusShoujiAnim(true);
        }
    },

    // 播放完成动画
    playCompleteAnim(){
        return new Promise(async (sucess, failed)=> {

            // 1.顶部横条显示 complete
            this.setTitleNum(-1);
            Global.SlotsSoundMgr.playEffect("");
            await this.awaitTime(1);
            this._node_tit.active = false;

            this._spine_jsKuang.active = true;
            this._spine_jsKuang.getComponent(sp.Skeleton).setAnimation(0, "animation", true);

            // 2.爆炸动画，停留动画
            Global.SlotsSoundMgr.playEffect("respin_light");
            let allSymList = [];
            let unlockRow = cc.vv.gameData.GetBonusRow().after;
            for (let row = unlockRow - 1; row >= 0; row--) {
                for (let col = 0; col < this._col; col++) {
                    let isPlay = this._reels[col].getHolderPlay(row);

                    if (!isPlay) {
                        let sym = this._reels[col].GetSymbolByRow(row);
                        this.playBonusBombAnim(sym);

                        allSymList.push(sym);
                    }
                }
            }

            await this.awaitTime(1.3);
            // 3.收集动画
            for (let i = 0; i < allSymList.length; i++){
                let sym = allSymList[i];
                sym.playBonusShoujiAnim(false);

                // 结算金额
                let symData = sym.GetData();
                let winCoin = symData.coin;
                if(symData.pool > 0){
                    let poolList  = cc.vv.gameData.GetBonusPool();
                    winCoin += poolList[symData.pool-1];
                }

                let isLock = true;
                if(symData.pool > 0){
                    cc.vv.gameData.GetPoolScript().showWinJp(symData.pool, true);

                    isLock = cc.vv.gameData.GetPoolScript().poolIsLock(symData.pool);
                    if(!isLock){
                        await cc.vv.gameData.GetPopupScript().showWinJp(winCoin, symData.pool);
                        cc.vv.gameData.GetPoolScript().showWinJp(symData.pool, false);
                    }
                }

                if(symData.pool <= 0 || isLock){

                    Global.SlotsSoundMgr.playEffect("win_fly");

                    let row = sym.getSymbolIdx();
                    let col = sym.getReelIdx();

                    this._spine_shouji.active = true;
                    let endNode = cc.vv.gameData.GetBottomScript().getWinLabelNor();
                    let startPos = this._spine_shouji.parent.convertToNodeSpaceAR(sym.node.convertToWorldSpaceAR(cc.v2(0,0)));
                    let endPos = this._spine_shouji.parent.convertToNodeSpaceAR(endNode.convertToWorldSpaceAR(cc.v2(0,0)));
                    let dPos = cc.v2(endPos.x-startPos.x, endPos.y-startPos.y);
                    let angle = dPos.signAngle(cc.v2(1,0));
                    this._spine_shouji.position = this._spine_shouji.parent.convertToNodeSpaceAR(sym.node.convertToWorldSpaceAR(cc.v2(0,0)));
                    this._spine_shouji.angle = -angle * cc.macro.DEG + 90;
                    this._spine_shouji.scaleY = Math.abs(dPos.mag())/750;
                    this._spine_shouji.getComponent(sp.Skeleton).setAnimation(0, "animation1_3",false);
                    await this.awaitTime(0.6);
                    this._spine_js.active = true;
                    this._spine_js.position = endPos;
                    this._spine_js.getComponent(sp.Skeleton).setAnimation(0,"animation",false);

                    if(symData.pool > 0){
                        cc.vv.gameData.GetPoolScript().showWinJp(symData.pool, false);
                    }
                }

                let nTotal = winCoin + this._bottomScript.getCurrentWin();
                this._bottomScript.SetWin(nTotal);

                await this.awaitTime(0.3)
            }

            // 4.赢钱奖励
            this._spine_jsKuang.active = false;
            let nWin = cc.vv.gameData.GetBonusWinCoin();
            await cc.vv.gameData.GetPopupScript().showBonusWin(nWin);

            sucess()
        })
    },


    // 发送下一次旋转请求
    sendNextRound(){
        this._bottomScript.SendSpinReq();
    },

    //自动停止时间
    //不配的话，就3s后停止
    GetStopTime:function(){
        return this._cfg.auto_stop_time || 1
    },

    //设置旋转停止时间
    //如果需要列不停止，可以将时间设置的很大。
    SetStopTime:function(nVal){
        this._stopTime = nVal
    },

    //每列停止时间间隔 = 每列的停止间隔 + 每列的回弹时间
    //reelIdx:0开始
    GetReelStopInter:function(reelIdx){
        let nIter = this._cfg.reelStopInter || 0.6
        return reelIdx*nIter
    },

    getColByIdx(idx){
        return (idx - 1) % this._col;
    },

    getRowByIdx(idx){
        return this._row - Math.floor((idx -1)/this._col) -1;
    },

    //根据服务端序号获取本地的symbol
    GetSymbolByIdx:function(idx){
        let col = (idx - 1) % this._col
        let row = this._row - Math.floor((idx -1)/this._col) -1
        return this._reels[col].GetSymbolByRow(row)
    },

    //获取最后一个停下来的列序号
    GetLastStopReelIdx:function(){
        return this.moveReelLastIdx
    },

    update (dt) {
        if(this._stopTime > 0){
            this._stopTime = this._stopTime - dt
            if(this._stopTime <= 0 ){ //空转时间到了
                this._bottomScript.ShowBtnsByState("moveing_2")
                //倒计时完，设置一次
                for(let i = 0; i < this._reels.length; i++ ){
                    let item = this._reels[i]
                    let reelStopInterv = this.GetReelStopInter(i)
                    item.StopMove(reelStopInterv)
                }

            }
        }


    },

    //奖池锁定(停止滚动)
    lockJackpot(){
        let poolList = cc.vv.gameData.GetBonusPool();
        cc.vv.gameData.GetPoolScript().PausePool([{prizeType:0,pauseNum:poolList[0]},{prizeType:1,pauseNum:poolList[1]},
            {prizeType:2,pauseNum:poolList[2]},{prizeType:3,pauseNum:poolList[3]},{prizeType:4,pauseNum:poolList[4]}]);
    },

    //复位奖池(继续滚动)
    resetJackpot(){
        cc.vv.gameData.GetPoolScript().ResumePausePool();
    },

    awaitTime(time){
        return new Promise((sucess, failed)=>{
            this.scheduleOnce(()=>{
                sucess()
            },time);
        });
    },
    // update (dt) {},
});
