cc.Class({
    extends: require("LMSlots_GameData_Base"),

    properties: {

    },

    // LIFE-CYCLE CALLBACKS:

    // onLoad () {},

    start () {

    },

    init(deskInfo,gameId,gameJackpot){

        this._bonusCfg = deskInfo.bonusGame.cfg;
        this._bonusInfo =  deskInfo.bonusGame.info
        this._bonusRestNum =  deskInfo.bonusGame.num
        this._bonusPoolList =  deskInfo.bonusGame.poolList
        this._bonusResult = deskInfo.bonusGame.result;
        this._bonusRow = deskInfo.bonusGame.row;
        this._bonusWinCoin = deskInfo.bonusGame.winCoin;

        this._collectData = deskInfo.collect;
        if(deskInfo.collect){
            this._collectCurNum = deskInfo.collect.num
        }

        this._freeWinCoin =  deskInfo.freeWinCoin;

        // this._freeBonusInfo =  deskInfo.freeBonusInfo;

        this._super(deskInfo,gameId,gameJackpot);
    },

    OnRcvNetSpine:function(msg){

        if(msg.code == 200) {

            this._bonusInfo = msg.bonusGame.info
            this._bonusRestNum = msg.bonusGame.num
            this._bonusPoolList = msg.bonusGame.poolList
            this._bonusResult = msg.bonusGame.result;
            this._bonusRow = msg.bonusGame.row;
            this._bonusWinCoin = msg.bonusGame.winCoin;

            this._collectData = msg.collect;
            if(msg.collect){
                this._collectCurNum = msg.collect.num
            }

            this._freeWinCoin = msg.freeWinCoin;

            // this._freeBonusInfo = msg.freeBonusInfo;

        }

        // msg.resultCards = [1,2,2,2,1, 7,7,7,7,7, 8,8,8,8,8, 8,8,8,8,8];
        // msg.freeResult={"freeInfo":{"idxs":[2,3,4],"freeCnt":2}};
        // msg.zjLuXian=[{"mult":1,"indexs":[6,7,8,9],"card":7,"xlid":1,"coin":3000},]

        this._super(msg);
    },

    SetCollectScript(scp){
        this._collectScp = scp;
    },

    GetCollectScript(){
        return this._collectScp;
    },

    SetPopupScript(scp){
        this._popupScp = scp;
    },

    GetPopupScript(){
        return this._popupScp;
    },

    SetBonusScript(scp){
        this._bonusScp = scp;
    },

    GetBonusScript(){
        return this._bonusScp;
    },

    SetPoolScript(scp){
        this._poolScp = scp;
    },

    GetPoolScript(){
        return this._poolScp;
    },

    SetIsBonusGame(isBonus){
        this._isBonusGame = isBonus;
    },

    IsBonusGame(){
        return this._isBonusGame;
    },

    // GetChangeNumBet(){
        // return this._deskInfo.bonusGame.tri.bet;
        // return 3
    // },

    GetBonusCfg(){
        this._bonusCfg.sort(function (a,b) {
            return b.row-a.row;
        });

        let list = [];
        for(let i = 0; i < this._bonusCfg.length; i++){
            list.push(this._bonusCfg[i].num);
        }
        return list;
    },

    GetBonusInfo(){
        return this._bonusInfo;
    },

    GetBonusState(){
        return this._deskInfo.bonusGame.state
    },

    GetBonusWinCoin(){
        return this._bonusWinCoin
    },

    GetBonusRestNum(){
        return this._bonusRestNum;
    },

    // bonus奖池数据
    GetBonusPool(){
        return this._bonusPoolList;
    },

    // bonus解锁行数 before-当前局开始时 after-当前局结束时
    GetBonusRow(){
        return this._bonusRow;
    },

    // bonus游戏弹弹弹数据
    // result":[{"red":{},"boost":{}},{},{}]   --每次弹的数据，result[0]为初始数据
    // "red":{} --红色宝石数据
    // "boost":{"idx":[],"showIdx":idx,"traceIdxs":[] } --黄色宝石数据 showIdx-这一轮弹的黄色宝石位置 traceIdxs-弹中的位置
    GetBonusResult(){
        return this._bonusResult;
    },

    // 开启收集最小押注额
    GetCollectMinBet(){
        return this._collectData.bet
    },

    SetCollectCurNum(num){
        this._collectCurNum = num;
    },

    // 当前收集个数
    GetCollectCurNum(){
        return this._collectCurNum;
    },

    // 最大收集个数
    GetCollectMaxNum(){
        return this._collectData.max
    },

    // 是否时超级游戏  0:否，1:是
    GetCollectSuper(){
        return this._collectData.super
    },

    GetFreeWinCoin(){
        return this._freeWinCoin;
    },

    // 免费游戏紫色宝石数据
    // GetFreeBonusInfo(){
    //     return this._freeBonusInfo;
    // },

    // 是否处于免费游戏中
    isFreeGame(){
        return this._isFreeGame;
    },

    SetIsFreeGame(bFree){
        this._isFreeGame = bFree;
    },

    // 随机图标深色
    setSymbolDark(bDark){
        this._symDark = bDark;
    },

    getSymbolDark(){
        return this._symDark;
    },
    // update (dt) {},
});
